//! One-letter codes of every polymer component of the Chemical Component
//! Dictionary, generated by `tools/components/codes.py`.

use std::sync::OnceLock;

use super::ComponentLinking;

const TABLE: &str = include_str!("../../../data/components/codes.tsv");

/// One dictionary component that links into a polypeptide or a
/// polynucleotide.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct DictionaryCode {
    pub(crate) id: &'static str,
    pub(crate) linking: ComponentLinking,
    /// `None` when the dictionary states no code.
    pub(crate) code: Option<&'static str>,
    /// Comma-separated parent identifiers; empty for none.
    pub(crate) parents: &'static str,
}

impl DictionaryCode {
    pub(crate) fn parents(self) -> impl Iterator<Item = &'static str> {
        self.parents.split(',').filter(|parent| !parent.is_empty())
    }
}

fn entries() -> &'static [DictionaryCode] {
    static ENTRIES: OnceLock<Vec<DictionaryCode>> = OnceLock::new();
    ENTRIES.get_or_init(|| {
        TABLE
            .lines()
            .filter(|line| !line.starts_with('#'))
            .map(|line| {
                let mut fields = line.split('\t');
                let mut field = || fields.next().expect("code table rows have four columns");
                let id = field();
                let linking = match field() {
                    "P" => ComponentLinking::Peptide,
                    "N" => ComponentLinking::Nucleotide,
                    other => panic!("code table linking `{other}` is P or N"),
                };
                let code = Some(field()).filter(|code| !code.is_empty());
                DictionaryCode {
                    id,
                    linking,
                    code,
                    parents: field(),
                }
            })
            .collect()
    })
}

/// The dictionary entry of a polymer component, compared case-insensitively.
pub(crate) fn dictionary_code(id: &str) -> Option<DictionaryCode> {
    let entries = entries();
    let id = id.trim();
    entries
        .binary_search_by(|entry| {
            entry
                .id
                .bytes()
                .cmp(id.bytes().map(|byte| byte.to_ascii_uppercase()))
        })
        .ok()
        .map(|index| entries[index])
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::io::ComponentLibrary;

    #[test]
    fn table_is_sorted_and_unique() {
        let entries = entries();
        assert!(entries.len() > 2_000);
        assert!(entries.windows(2).all(|pair| pair[0].id < pair[1].id));
    }

    #[test]
    fn modified_residues_carry_their_parent_codes() {
        let threonine = dictionary_code("tpo").expect("phosphothreonine");
        assert_eq!(threonine.linking, ComponentLinking::Peptide);
        assert_eq!(threonine.code, Some("T"));
        assert_eq!(threonine.parents().collect::<Vec<_>>(), ["THR"]);
        let pseudouridine = dictionary_code("PSU").expect("pseudouridine");
        assert_eq!(pseudouridine.linking, ComponentLinking::Nucleotide);
        assert_eq!(pseudouridine.code, Some("U"));
        assert_eq!(dictionary_code("HOH"), None);
    }

    #[test]
    fn bundled_polymer_templates_agree_with_the_table() {
        for component in ComponentLibrary::bundled().components() {
            let linking = component.linking();
            if !matches!(
                linking,
                ComponentLinking::Peptide | ComponentLinking::Nucleotide
            ) {
                continue;
            }
            let entry = dictionary_code(component.id()).expect("bundled polymer component");
            assert_eq!(entry.linking, linking, "{}", component.id());
            assert_eq!(
                entry.code,
                component.one_letter_code(),
                "{}",
                component.id()
            );
            assert!(
                entry
                    .parents()
                    .eq(component.parent_ids().iter().map(String::as_str)),
                "{}",
                component.id()
            );
        }
    }
}
